# Generated by qa-agent from cases/bookings.yaml. Do not edit: change the cases, then run qa-agent generate.
"""Bookings: 4 cases, one test each."""

import pytest

from api_test_framework import Expect, unique_id


@pytest.mark.functional
@pytest.mark.smoke
@pytest.mark.writes
@pytest.mark.case("TC001")
@pytest.mark.priority("P1")
def test_tc001_a_new_booking_can_be_read_back_by_its_pnr(api, context):
    """A new booking can be read back by its PNR. Criteria: AC-1."""
    unique = unique_id()
    # 1. POST /bookings
    response = api.post("/bookings", json={
        "passenger_name": f"Neha Iyer {unique}",
        "email": f"neha.{unique}@testdata.example",
        "amount": 180,
    })
    Expect(response).status_is(201)
    context.remember("pnr", response.value("pnr"))
    # 2. GET /bookings/{{pnr}}
    response = api.get(f"/bookings/{context.get('pnr')}")
    (Expect(response).status_is(200)
        .field_equals("pnr", context.get("pnr"))
        .field_equals("amount", 180)
        .field_equals("status", "active"))


@pytest.mark.functional
@pytest.mark.writes
@pytest.mark.case("TC002")
@pytest.mark.priority("P1")
def test_tc002_a_deleted_booking_can_no_longer_be_read(api, context):
    """A deleted booking can no longer be read. Criteria: AC-2."""
    unique = unique_id()
    # 1. POST /bookings
    response = api.post("/bookings", json={
        "passenger_name": f"Neha Iyer {unique}",
        "email": f"neha.{unique}@testdata.example",
        "amount": 180,
    })
    Expect(response).status_is(201)
    context.remember("pnr", response.value("pnr"))
    # 2. DELETE /bookings/{{pnr}}
    response = api.delete(f"/bookings/{context.get('pnr')}")
    Expect(response).status_is(204)
    # 3. GET /bookings/{{pnr}}
    response = api.get(f"/bookings/{context.get('pnr')}")
    Expect(response).status_is(404).field_equals("error.code", "booking_not_found")


@pytest.mark.functional
@pytest.mark.writes
@pytest.mark.case("TC003")
@pytest.mark.priority("P2")
def test_tc003_a_cancelled_booking_is_listed_as_cancelled_not_as_active(api, context):
    """A cancelled booking is listed as cancelled, not as active. Criteria: AC-3."""
    unique = unique_id()
    # 1. POST /bookings
    response = api.post("/bookings", json={
        "passenger_name": f"Neha Iyer {unique}",
        "email": f"neha.{unique}@testdata.example",
        "amount": 180,
    })
    Expect(response).status_is(201)
    context.remember("pnr", response.value("pnr"))
    # 2. POST /bookings/{{pnr}}/cancel
    response = api.post(f"/bookings/{context.get('pnr')}/cancel")
    Expect(response).status_is(200)
    # 3. GET /bookings
    response = api.get("/bookings", params={"status": "cancelled", "limit": 100})
    Expect(response).status_is(200).list_contains("items", **{"pnr": context.get("pnr")})
    # 4. GET /bookings
    response = api.get("/bookings", params={"status": "active", "limit": 100})
    Expect(response).status_is(200).list_excludes("items", **{"pnr": context.get("pnr")})


@pytest.mark.functional
@pytest.mark.negative
@pytest.mark.case("TC004")
@pytest.mark.priority("P0")
def test_tc004_without_a_token_bookings_cant_be_read(api, context):
    """Without a token, bookings can't be read. Criteria: AC-4."""
    # 1. GET /bookings
    response = api.without_auth().get("/bookings")
    Expect(response).status_is(401).field_equals("error.code", "unauthorized")
